head.script:
// 컴포넌트·전역 이름 조회(엔진 캐시 → 이름 그대로 실행 → mf_ 접두사 붙여 다시, 없으면 받은 id 문자열 반환). 2026-11
scwin.__getObj = function(id) {
    if (typeof id !== 'string') return id;
    var W = WebSquare, C = W.idCache, U = W.idToUUID, F = function(k) { return new Function('return ' + k)(); };
    if (!W.strictMode) id = id.replace(/mf_/g, '');
    if (C[U[id]]) return C[U[id]];
    var r; try { r = F(id); } catch (e) {}
    if (r == undefined && W.strictMode) {
        var P = W.strictModeFrame.id + '_';
        var s = id.slice(0, 2) === 'G_' ? 'G_' + P + id.slice(2) : (id.slice(0, P.length) !== P ? P + id : id);
        s = s.replace(new RegExp('(' + P + '){2,}', 'g'), P);
        if (C[U[s]]) r = C[U[s]]; else { try { r = F(s); } catch (e) { r = id; } }
    }
    return r == undefined ? id : r;
};
scwin.trigger1_onclick = function(e) {
    scwin.bFormatter = function() {
        return [{
                'id': 'custombtn',
                'className': 'w2widget_btnCustom',
                'isCustom': true
            },
            {
                'id': 'custombtn2',
                'className': 'w2widget_btnCustom',
                'isCustom': true
            },
            {
                'id': 'custombtn3',
                'className': 'w2widget_btnCustom3',
                'isCustom': true
            },
            {
                'useDefault': 'maximize'
            },
            {
                'useDefault': 'close'
            }
        ];
    };
    scwin.mFormatter = function() {
        return {
            top: 2,
            bottom: 3,
            left: -1,
            right: 0
        };
    }
    count++;
    widgetContainer1.addWidgets({
        id: "widget" + count,
        title: "위젯" + count,
        src: "widget.xml",
        scope: true,
        x: 0,
        y: 0,
        unitWidth: 1,
        unitHeight: 1,
        buttonFormatter: scwin.bFormatter,
        maximizeFormatter: scwin.mFormatter
    });
};
scwin.bFormatter = function() {
    return [{
            'id': 'custombtn',
            'className': 'w2widget_btnCustom',
            'isCustom': true
        },
        {
            'id': 'custombtn2',
            'className': 'w2widget_btnCustom',
            'isCustom': true
        },
        {
            'id': 'custombtn3',
            'className': 'w2widget_btnCustom3',
            'isCustom': true
        },
        {
            'useDefault': 'maximize'
        },
        {
            'useDefault': 'close'
        }
    ];
};
scwin.mFormatter = function() {
    return {
        top: 2,
        bottom: 3,
        left: -1,
        right: 0
    };
}
